{
  "packet_id": "H6-T04-1",
  "claim_id": "C050",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C050.component",
    "value": "Because retention behavior alone does not identify a cause, corroboration should be sought through preparation reports, task observation or a controlled intervention.",
    "scope": "Proposed avenues for corroboration, not a guarantee that any one avenue establishes the cause.",
    "provenance": {
      "refs": [
        {
          "source_id": "P027",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly connects the causal identification limit to these three corroboration methods."
    }
  },
  "signal_basis": {
    "component_id": "C050.signal_basis",
    "value": "Under common observation conditions, onboarding trajectories show separated concentrations in milestone position, waiting duration, returns to active work and time to first publication. These patterns remain compatible with different or multiple causes; absent events cannot distinguish abandonment from offline preparation.",
    "scope": "Behavioral observations in the prospective cohort of newly created accounts; the observed differences do not uniquely identify their causes.",
    "provenance": {
      "refs": [
        {
          "source_id": "P001",
          "role": "CONTEXT"
        },
        {
          "source_id": "P004",
          "role": "SUPPORT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P023",
          "role": "SUPPORT"
        },
        {
          "source_id": "P024",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The bundle supplies the cohort identity, common observation conditions, trajectory signal and explicit limits on causal interpretation."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C050.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported within its stated bounds; no unresolved empirical relation is required to license the recommendation."
    }
  },
  "rationale": "Observing differences in retention does not resolve causal ambiguity when several causes can produce the same pattern. Seeking evidence about preparation, actual task performance or responses to a controlled intervention is therefore warranted. The claim recommends corroboration without asserting that any method necessarily establishes the cause.",
  "uncertainty": "Which cause explains a particular trajectory, and whether a chosen corroboration method will resolve it, remain open. Neither uncertainty undermines this bounded recommendation.",
  "anomalies": []
}
